// BUG FIX #1: Extract verification_token and phone from body
// BUG FIX #2: Build Base Profile now reads from auth response (Create Auth User) AND original body
const body = $('Signup Webhook').first().json.body || $('Signup Webhook').first().json;
const authData = $('Create Auth User in Supabase').first().json;

function generateHex(length) {
  const chars = '0123456789abcdef';
  let hex = '';
  for (let i = 0; i < length; i++) {
    hex += chars[Math.floor(Math.random() * 16)];
  }
  return hex;
}

function generateSubmissionKey() {
  return 'EE_' + generateHex(32);
}

const user_id    = authData.id || body.user_id || body.record?.id;
const email      = body.email  || body.record?.email;
const full_name  = body.full_name || body.record?.user_metadata?.full_name || '';
const username   = body.username || '';
const title      = body.title    || '';
const state      = body.state    || '';
const phone      = body.phone    || body.phone_number || null;  // FIX: capture phone
const role       = body.role     || 'user';
const submission_key     = generateSubmissionKey();
const created_at         = new Date().toISOString();
const verification_status = body.verification_status || 'pending';
const email_verified = Boolean(body.email_verified ?? false);
const is_verified = Boolean(body.is_verified ?? false);
const verified_at = body.verified_at || null;
const auth_source = body.auth_source || 'n8n';
const account_status = body.account_status || 'pending_verification';
// FIX: Generate 6-digit OTP here so it's available for both email and DB save
const verification_token = Math.floor(100000 + Math.random() * 900000).toString();

return [{
  json: {
    user_id,
    email,
    full_name,
    username,
    title,
    state,
    phone,
    role,
    submission_key,
    created_at,
    verification_token,
    echo_id: submission_key,
    verification_status,
    email_verified,
    is_verified,
    verified_at,
    auth_source,
    account_status
  }
}];
